<script setup lang="ts">
import { availabilityReasonLabels, qualityLabels, type InventoryResponse, type Material, type MaterialStockSummary, type Paginated, type StorageLocation, type Warehouse } from '#shared/types/inventory'

definePageMeta({ middleware: 'auth' })
useSeoMeta({ title: '재고 조회 · Warehouse AI' })
const { fetchWithSession } = useAuth()
const { route, filters, page, apply, reset, setPage } = useInventoryQuery({ q: '', view: 'detail', material_id: '', manufacturer: '', warehouse_id: '', location_id: '', status: '', retest: '', expiry: '', low_stock: '' })
const summaryMode = computed(() => route.query.view === 'summary')
const detailFields = ['q', 'material_id', 'manufacturer', 'warehouse_id', 'location_id', 'status', 'retest', 'expiry', 'low_stock', 'page']
function params(summary = false) {
  const result = new URLSearchParams()
  for (const key of summary ? ['q', 'low_stock', 'page'] : detailFields) {
    const value = route.query[key]
    if (typeof value === 'string' && value) result.set(key, value)
  }
  return result.toString()
}
const { data: detail, error: detailError, status: detailStatus, refresh: refreshDetail } = await useAsyncData('inventory-detail', () => summaryMode.value ? Promise.resolve(null) : fetchWithSession<InventoryResponse>(`/api/inventory?${params()}`), { watch: [() => route.fullPath] })
const { data: summary, error: summaryError, status: summaryStatus, refresh: refreshSummary } = await useAsyncData('inventory-summary', () => summaryMode.value ? fetchWithSession<Paginated<MaterialStockSummary>>(`/api/inventory/summary?${params(true)}`) : Promise.resolve(null), { watch: [() => route.fullPath] })
const error = computed(() => summaryMode.value ? summaryError.value : detailError.value)
const pending = computed(() => (summaryMode.value ? summaryStatus.value : detailStatus.value) === 'pending')
const total = computed(() => (summaryMode.value ? summary.value?.total : detail.value?.total) ?? 0)
const pageSize = computed(() => (summaryMode.value ? summary.value?.pageSize : detail.value?.pageSize) ?? 20)
async function refresh() { if (summaryMode.value) await refreshSummary(); else await refreshDetail() }
async function switchView(view: 'detail' | 'summary') { filters.view = view; await apply() }
async function loadOptions<T>(endpoint: string): Promise<T[]> {
  const rows: T[] = []
  let nextPage = 1
  while (true) {
    const data = await fetchWithSession<Paginated<T>>(`${endpoint}${endpoint.includes('?') ? '&' : '?'}pageSize=100&page=${nextPage}`)
    rows.push(...data.items)
    if (!data.items.length || rows.length >= data.total) return rows
    nextPage++
  }
}
const { data: warehouses, error: warehousesError, refresh: refreshWarehouses } = await useAsyncData('inventory-warehouse-options', () => loadOptions<Warehouse>('/api/warehouses'))
const { data: locations, error: locationsError, refresh: refreshLocations } = await useAsyncData('inventory-location-options', () => filters.warehouse_id ? loadOptions<StorageLocation>(`/api/locations?warehouse_id=${encodeURIComponent(filters.warehouse_id)}`) : Promise.resolve([]), { watch: [() => filters.warehouse_id] })
const { data: selectedMaterial } = await useAsyncData('inventory-selected-material', () => typeof route.query.material_id === 'string' ? fetchWithSession<Material>(`/api/materials/${encodeURIComponent(route.query.material_id)}`) : Promise.resolve(null), { watch: [() => route.query.material_id] })
const warehouseItems = computed(() => [{ label: '전체 창고', value: 'all' }, ...(warehouses.value ?? []).map(row => ({ label: `${row.name}${row.is_active ? '' : ' (사용 중지)'}`, value: row.id }))])
const locationItems = computed(() => [{ label: '전체 위치', value: 'all' }, ...(locations.value ?? []).map(row => ({ label: `${row.code} · ${row.name}${row.is_active ? '' : ' (사용 중지)'}`, value: row.id }))])
const qualityItems = [{ label: '전체 품질상태', value: 'all' }, ...Object.entries(qualityLabels).map(([value, label]) => ({ label, value }))]
const warehouseFilter = computed({ get: () => filters.warehouse_id || 'all', set: (value: string) => { filters.warehouse_id = value === 'all' ? '' : value; filters.location_id = '' } })
const locationFilter = computed({ get: () => filters.location_id || 'all', set: (value: string) => { filters.location_id = value === 'all' ? '' : value } })
const qualityFilter = computed({ get: () => filters.status || 'all', set: (value: string) => { filters.status = value === 'all' ? '' : value } })
async function clearMaterial() { filters.material_id = ''; await apply() }
</script>

<template>
  <div class="space-y-6">
    <div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-[10px] font-semibold tracking-[.18em] text-slate-400">INVENTORY EXPLORER</p><h1 class="mt-2 text-[27px] font-bold text-slate-900">재고 조회</h1><p class="mt-2 text-xs text-slate-500">원료부터 제조 LOT, 입고건과 보관위치까지 재고를 확인합니다.</p></div><div class="flex gap-2"><UButton color="neutral" variant="outline" icon="i-lucide-refresh-cw" :loading="pending" class="bg-white" @click="refresh">새로고침</UButton><UButton v-if="!summaryMode" :href="`/api/inventory/export?${params()}`" external color="neutral" variant="outline" icon="i-lucide-download" class="bg-white">CSV 내려받기</UButton></div></div>
    <div class="flex w-fit gap-1 rounded-lg border border-slate-200 bg-white p-1" aria-label="재고 조회 방식"><UButton :color="!summaryMode ? 'primary' : 'neutral'" :variant="!summaryMode ? 'soft' : 'ghost'" :aria-pressed="!summaryMode" icon="i-lucide-list" @click="switchView('detail')">LOT · 위치별</UButton><UButton :color="summaryMode ? 'primary' : 'neutral'" :variant="summaryMode ? 'soft' : 'ghost'" :aria-pressed="summaryMode" icon="i-lucide-chart-no-axes-column" @click="switchView('summary')">원료별 합계</UButton></div>
    <form class="space-y-4 rounded-xl border border-slate-200/80 bg-white p-5" @submit.prevent="apply">
      <div class="grid items-end gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <UFormField label="재고 검색" :class="summaryMode ? 'sm:col-span-2 xl:col-span-3' : 'sm:col-span-2'"><UInput v-model="filters.q" :placeholder="summaryMode ? '원료코드, 원료명, 약어' : '원료코드, 원료명, 약어, 제조번호, 시험번호'" icon="i-lucide-search" class="w-full" /></UFormField>
        <template v-if="!summaryMode"><UFormField label="제조사"><UInput v-model="filters.manufacturer" placeholder="제조사 검색" class="w-full" /></UFormField><UFormField label="품질상태"><USelect v-model="qualityFilter" :items="qualityItems" class="w-full" /></UFormField><UFormField label="창고"><USelect v-model="warehouseFilter" :items="warehouseItems" class="w-full" /></UFormField><UFormField label="보관위치"><USelect v-model="locationFilter" :items="locationItems" :disabled="!filters.warehouse_id" class="w-full" /></UFormField></template>
        <div class="flex flex-wrap items-center gap-4 pb-1" :class="summaryMode ? '' : 'sm:col-span-2'"><UCheckbox :model-value="filters.low_stock === 'true'" label="재고 부족" @update:model-value="filters.low_stock = $event ? 'true' : ''" /><template v-if="!summaryMode"><UCheckbox :model-value="filters.retest === 'true'" label="재시험 예정" @update:model-value="filters.retest = $event ? 'true' : ''" /><UCheckbox :model-value="filters.expiry === 'true'" label="유효기간 임박" @update:model-value="filters.expiry = $event ? 'true' : ''" /></template></div>
      </div>
      <div class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-4"><div class="text-[11px] text-slate-400"><template v-if="summaryMode">원료 합계는 전체 창고와 품질상태를 합산합니다. 원료 검색과 부족 여부로 필터링합니다.</template><template v-else>재시험 예정: 경과 또는 30일 이내 · 유효기간 임박: 30일 이내</template></div><div class="flex gap-2"><UButton type="submit" icon="i-lucide-search">조회</UButton><UButton color="neutral" variant="ghost" @click="reset">초기화</UButton></div></div>
      <div v-if="filters.material_id && !summaryMode" class="flex items-center gap-2 text-xs text-blue-600"><UIcon name="i-lucide-filter" class="size-3" />원료 지정: {{ selectedMaterial?.name ?? '선택된 원료' }}<UButton size="xs" color="neutral" variant="ghost" icon="i-lucide-x" aria-label="원료 지정 해제" @click="clearMaterial" /></div>
    </form>
    <UAlert v-if="warehousesError || locationsError" color="warning" variant="soft" title="창고 또는 보관위치 선택 항목을 불러오지 못했습니다"><template #actions><UButton color="warning" variant="outline" @click="refreshWarehouses(); refreshLocations()">다시 시도</UButton></template></UAlert>
    <UAlert v-if="error" color="error" variant="soft" title="재고를 불러오지 못했습니다" :description="inventoryErrorMessage(error)"><template #actions><UButton color="error" variant="outline" @click="refresh">다시 시도</UButton></template></UAlert>
    <section class="overflow-hidden rounded-xl border border-slate-200/80 bg-white" :aria-busy="pending">
      <div class="flex items-center justify-between gap-3 p-5"><h2 class="text-sm font-semibold text-slate-800">{{ summaryMode ? '원료별 재고 합계' : 'LOT · 입고건 · 위치별 재고' }}</h2><p class="text-[11px] text-slate-400">{{ pending ? '조회 중…' : `${total.toLocaleString('ko-KR')}건 조회` }}<span v-if="detail?.asOf && !summaryMode" class="ml-2 hidden sm:inline">{{ inventoryDate(detail.asOf) }} 기준</span></p></div>
      <p v-if="pending" role="status" class="px-5 pb-3 text-xs text-blue-600">재고를 불러오는 중입니다…</p>
      <div class="overflow-x-auto">
        <table v-if="!summaryMode" class="w-full min-w-[1420px] text-left text-xs"><caption class="sr-only">LOT, 입고건, 보관위치별 재고</caption><thead class="border-y border-slate-100 bg-slate-50 text-slate-500"><tr><th class="px-5 py-3 font-medium">원료 / 제조사</th><th class="px-4 py-3 font-medium">LOT / 시험번호</th><th class="px-4 py-3 font-medium">입고건 / 입고일</th><th class="px-4 py-3 font-medium">창고 / 위치</th><th class="px-4 py-3 font-medium">품질상태</th><th class="px-4 py-3 font-medium">유효기간 / 재시험일</th><th class="px-4 py-3 text-right font-medium">현재고</th><th class="px-4 py-3 text-right font-medium">예약</th><th class="px-4 py-3 text-right font-medium">가용</th><th class="px-4 py-3 text-right font-medium">사용불가</th><th class="px-5 py-3 font-medium">단위</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="row in detail?.items" :key="row.id" class="hover:bg-slate-50/60"><td class="px-5 py-4"><NuxtLink :to="`/materials/${row.material_id}`" class="font-semibold text-blue-600 hover:underline">{{ row.material_name }}</NuxtLink><p class="mt-1 text-[11px] text-slate-400">{{ row.material_code }} · {{ row.manufacturer || '제조사 미등록' }}</p><div class="mt-1 flex gap-1"><UBadge v-if="row.is_low_stock" color="warning" variant="soft" size="sm">원료 부족</UBadge><UBadge v-if="!row.material_active" color="neutral" variant="soft" size="sm">사용 중지</UBadge></div></td><td class="px-4 py-4 font-medium">{{ row.lot_number }}<p class="mt-1 text-[11px] font-normal text-slate-400">{{ row.test_number || '시험번호 없음' }}</p></td><td class="px-4 py-4">{{ row.receipt_reference }}<p class="mt-1 text-[11px] text-slate-400">{{ inventoryDate(row.received_on) }}</p></td><td class="px-4 py-4">{{ row.warehouse_name }}<p class="mt-1 text-[11px] text-slate-400">{{ row.location_code }} · {{ row.location_name }}</p></td><td class="px-4 py-4"><UBadge :color="inventoryStatusColor(row.effective_status)" variant="subtle" size="sm">{{ qualityLabels[row.effective_status] }}</UBadge><p v-if="row.effective_status === 'EXPIRED'" class="mt-1 text-[10px] text-slate-400">QC: {{ qualityLabels[row.quality_status] }}</p><p v-if="row.availability_reason" class="mt-1 text-[10px] text-rose-600">{{ availabilityReasonLabels[row.availability_reason] }}</p></td><td class="whitespace-nowrap px-4 py-4"><p :class="row.expiry_due ? 'text-amber-600' : ''">{{ inventoryDate(row.expires_on) }}<span v-if="row.expiry_due" class="ml-1 text-[10px]">임박</span></p><p class="mt-1 text-[11px]" :class="row.retest_due ? 'text-amber-600' : 'text-slate-400'">{{ inventoryDate(row.retest_on) }}<span v-if="row.retest_due" class="ml-1 text-[10px]">재시험</span></p></td><td class="px-4 py-4 text-right font-medium tabular-nums">{{ inventoryQuantity(row.on_hand) }}</td><td class="px-4 py-4 text-right tabular-nums text-slate-500">{{ inventoryQuantity(row.reserved) }}</td><td class="px-4 py-4 text-right font-semibold tabular-nums text-blue-600">{{ inventoryQuantity(row.available) }}</td><td class="px-4 py-4 text-right tabular-nums" :class="row.unavailable > 0 ? 'text-rose-600' : 'text-slate-400'">{{ inventoryQuantity(row.unavailable) }}</td><td class="px-5 py-4 text-slate-500">{{ row.base_unit }}</td></tr><tr v-if="!detail?.items.length && !pending"><td colspan="11" class="px-5 py-16 text-center text-slate-400"><UIcon name="i-lucide-package-open" class="mx-auto mb-3 block size-8 text-slate-300" />조건에 맞는 재고가 없습니다.</td></tr></tbody></table>
        <table v-else class="w-full min-w-[1050px] text-left text-xs"><caption class="sr-only">원료별 전체 재고 합계</caption><thead class="border-y border-slate-100 bg-slate-50 text-slate-500"><tr><th class="px-5 py-3 font-medium">원료코드 / 원료명</th><th class="px-4 py-3 font-medium">LOT / 입고건</th><th class="px-4 py-3 text-right font-medium">현재고</th><th class="px-4 py-3 text-right font-medium">예약</th><th class="px-4 py-3 text-right font-medium">가용</th><th class="px-4 py-3 text-right font-medium">사용불가</th><th class="px-4 py-3 text-right font-medium">최소재고</th><th class="px-4 py-3 font-medium">단위</th><th class="px-5 py-3 font-medium">상태</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="row in summary?.items" :key="row.material_id" class="hover:bg-slate-50/60"><td class="px-5 py-4"><NuxtLink :to="`/materials/${row.material_id}`" class="font-semibold text-blue-600 hover:underline">{{ row.material_name }}</NuxtLink><p class="mt-1 text-[11px] text-slate-400">{{ row.material_code }}</p></td><td class="px-4 py-4 text-slate-500">{{ row.lot_count }} / {{ row.batch_count }}</td><td class="px-4 py-4 text-right font-medium tabular-nums">{{ inventoryQuantity(row.on_hand) }}</td><td class="px-4 py-4 text-right tabular-nums text-slate-500">{{ inventoryQuantity(row.reserved) }}</td><td class="px-4 py-4 text-right font-semibold tabular-nums text-blue-600">{{ inventoryQuantity(row.available) }}</td><td class="px-4 py-4 text-right tabular-nums" :class="row.unavailable > 0 ? 'text-rose-600' : 'text-slate-400'">{{ inventoryQuantity(row.unavailable) }}</td><td class="px-4 py-4 text-right tabular-nums text-slate-500">{{ inventoryQuantity(row.min_stock) }}</td><td class="px-4 py-4 text-slate-500">{{ row.base_unit }}</td><td class="px-5 py-4"><div class="flex gap-1"><UBadge v-if="!row.is_active" color="neutral" variant="subtle" size="sm">사용 중지</UBadge><UBadge v-if="row.is_low_stock" color="warning" variant="subtle" size="sm">부족</UBadge><UBadge v-if="row.is_active && !row.is_low_stock" color="success" variant="subtle" size="sm">정상</UBadge></div></td></tr><tr v-if="!summary?.items.length && !pending"><td colspan="9" class="px-5 py-16 text-center text-slate-400">조건에 맞는 원료가 없습니다.</td></tr></tbody></table>
      </div>
      <InventoryPagination :total="total" :page="page" :page-size="pageSize" :busy="pending" @change="setPage" />
    </section>
    <div class="grid gap-4 sm:grid-cols-2"><div class="rounded-lg border border-blue-100 bg-blue-50/60 p-4"><p class="text-xs font-medium text-blue-900">가용재고와 품질상태</p><p class="mt-2 text-[11px] leading-6 text-blue-800/70">가용재고는 사용 가능한 적합 재고에서 예약 수량을 제외한 값입니다. 시험대기·부적합·사용보류·기한 경과·유효기간 미확인 재고와 사용 중지된 원료·창고·위치의 재고는 가용 수량이 0입니다.</p></div><div class="rounded-lg border border-slate-200 bg-white p-4"><p class="text-xs font-medium text-slate-700">원료 기본단위로 조회</p><p class="mt-2 text-[11px] leading-6 text-slate-500">수량은 각 원료의 기본단위로 표시합니다. 서로 다른 단위의 수량은 합산하지 않습니다. 재고 수량 변경은 Phase 3 입출고 기능에서 제공합니다.</p></div></div>
  </div>
</template>
